import { Logger } from '@nestjs/common';
import { getDocument, listDocumentKeys } from '../../utils/aws/s3.js';

/**
 * An AWS account a business has handed us for measurement.
 */
export class MeteredAccount {
    /**
     * The account the metering role lives in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * The role we assume to read the account.
     * @example "arn:aws:iam::445566778899:role/metering-metering"
     */
    public roleArn: string;
    /**
     * The external id the role's trust policy asks for, when it asks for one.
     */
    public externalId?: string;
    /**
     * The region the business runs the metered workload in.
     * @example "us-east-1"
     */
    public region: string;
}

/**
 * One account a customer has been onboarded onto.
 */
export class CustomerAccountEnrollment {
    /**
     * The account the customer's workload runs in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * Set when the business runs the account for this customer alone, so
     * anything metered in it is the customer's whatever the instance tags say.
     */
    public dedicated?: boolean;
}

/**
 * The per customer onboarding record kept in the metering bucket, one object per
 * customer under the registry's customer record prefix. A customer only becomes
 * billable for an account once such a record names it.
 */
export class CustomerOnboardingRecord {
    public customerId: string;
    public displayName?: string;
    public accounts: Array<CustomerAccountEnrollment>;
}

/**
 * Who is genuinely onboarded for a single account, resolved from the customer
 * onboarding records.
 */
export class AccountTenancy {
    public accountId: string;
    /**
     * The billable customers onboarded for the account, sorted for stable
     * attribution.
     */
    public customerIds: Array<string>;
    /**
     * Set when the account belongs to exactly one customer. Usage metered in a
     * dedicated account is that customer's regardless of the instance tags.
     */
    public dedicatedTo?: string;

    constructor({ accountId, customerIds, dedicatedTo }: AccountTenancy) {
        this.accountId = accountId;
        this.customerIds = customerIds;
        this.dedicatedTo = dedicatedTo;
    }
}

/**
 * The onboarding record a business keeps in its metering bucket. It is written
 * by the onboarding flow and read by every collector that has to sweep more
 * than one account.
 */
export class MeteringRegistry {
    private static readonly logger = new Logger(MeteringRegistry.name);
    public businessID: string;
    /**
     * Key prefix the per customer onboarding records sit under in the same
     * bucket, one object per customer.
     * @example "onboarding/customers/"
     */
    public customerRecordPrefix: string;
    public accounts: Array<MeteredAccount>;

    static async load(bucket: string, key: string): Promise<MeteringRegistry> {
        return getDocument<MeteringRegistry>(bucket, key);
    }

    /**
     * Reads every customer onboarding record kept beside the registry. A record
     * that cannot be read is skipped rather than failing the whole sweep, its
     * usage simply stays unplaceable.
     */
    static async loadCustomerRecords(bucket: string, prefix: string): Promise<Array<CustomerOnboardingRecord>> {
        if (!prefix) {
            MeteringRegistry.logger.warn('Metering registry has no customer record prefix, nothing is billable');
            return [];
        }
        const keys = await listDocumentKeys(bucket, prefix);
        const records = await Promise.all(
            keys.map(async (key) => {
                try {
                    return await getDocument<CustomerOnboardingRecord>(bucket, key);
                } catch (error) {
                    MeteringRegistry.logger.error(`Could not read customer onboarding record ${key}`, error);
                    return undefined;
                }
            }),
        );
        return records.filter((record) => record?.customerId);
    }

    /**
     * Works out, per account, which customers are genuinely onboarded for it and
     * whether the account is dedicated to a single one of them.
     */
    static resolveTenancy(records: Array<CustomerOnboardingRecord>): Record<string, AccountTenancy> {
        const tenants: Record<string, Array<string>> = {};
        const dedicatedClaims: Record<string, Array<string>> = {};
        records.forEach(({ customerId, accounts }) => {
            (accounts ?? []).forEach((enrollment) => {
                const accountId = enrollment?.accountId;
                if (!accountId || !customerId) {
                    return;
                }
                tenants[accountId] = tenants[accountId] ?? [];
                if (!tenants[accountId].includes(customerId)) {
                    tenants[accountId].push(customerId);
                }
                if (enrollment.dedicated) {
                    dedicatedClaims[accountId] = (dedicatedClaims[accountId] ?? []).concat(customerId);
                }
            });
        });

        return Object.keys(tenants).reduce((tenancy, accountId) => {
            const customerIds = tenants[accountId].sort();
            const claims = [...new Set(dedicatedClaims[accountId] ?? [])];
            let dedicatedTo: string | undefined;
            if (customerIds.length === 1) {
                dedicatedTo = customerIds[0];
            } else if (claims.length === 1) {
                dedicatedTo = claims[0];
                MeteringRegistry.logger.warn(
                    `Account ${accountId} is onboarded for ${customerIds.length} customers but ${dedicatedTo} claims it as dedicated, treating it as dedicated`,
                );
            } else if (claims.length > 1) {
                MeteringRegistry.logger.warn(
                    `Account ${accountId} is claimed as dedicated by ${claims.length} customers, treating it as shared`,
                );
            }
            tenancy[accountId] = new AccountTenancy({ accountId, customerIds, dedicatedTo });
            return tenancy;
        }, {} as Record<string, AccountTenancy>);
    }

    /**
     * Convenience wrapper that reads the customer onboarding records beside the
     * registry and resolves them into per account tenancy.
     */
    static async loadTenancy(bucket: string, prefix: string): Promise<Record<string, AccountTenancy>> {
        return MeteringRegistry.resolveTenancy(await MeteringRegistry.loadCustomerRecords(bucket, prefix));
    }
}
