            const owners = Ec2InstanceDataGathererService.resolveOwners(instance, tenancy[instance.accountId]);
            if (owners.length === 0) {
                unplaceable += 1;
                Ec2InstanceDataGathererService.logger.warn(
                    `Dropping unplaceable usage for instance ${instance.instanceId} in account ${instance.accountId}`,
                );
                return;
            }
            const share = RUNNING_TIME_INCREMENT / owners.length;
            owners.forEach((customerId) => {
                runningTime[customerId] = (runningTime[customerId] ?? 0) + share;
                instanceIds[customerId] = (instanceIds[customerId] ?? []).concat(instance.instanceId);
            });
        });
        if (unplaceable > 0) {
            Ec2InstanceDataGathererService.logger.log(
                `Left ${unplaceable} instances off the bill, no onboarded customer could be resolved for them`,
            );
